/// <summary>
/// Starts a database refresh job from the menu, the workspace or as a batch job.
/// </summary>
public final class BDRJobController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super(classStr(BDRJobService), methodStr(BDRJobService, process), SysOperationExecutionMode::Synchronous);
}

    /// <summary>
    /// Creates the controller.
    /// </summary>
    /// <param name = "_executionMode">Synchronous for the menu, scheduled batch for the service.</param>
    /// <returns>The controller.</returns>
    public static BDRJobController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        BDRJobController controller = new BDRJobController();

        controller.parmExecutionMode(_executionMode);

        return controller;
    }

public static void main(Args _args)
{
    BDRJobController controller = BDRJobController::construct();
    controller.parmLoadFromSysLastValue(false);
    BDREnvironment bdrEnvironment = BDREnvironmentResolver::resolve();
    BDRJobContract bdrJobContract = controller.getDataContractObject() as BDRJobContract;
    bdrJobContract.parmEnvironmentId(bdrEnvironment.EnvironmentId);
    controller.parmArgs(_args);
    controller.startOperation();
}
